INSERT INTO fut_club_players VALUES(144,1,11,264209,'보가르드','2026-09-19','GG Club 싱크','owned',79,'{"PAC": 75, "SHO": 53, "PAS": 78, "DRI": 70, "DEF": 77, "PHY": 76}','Tiki Taka','[4, 14, 16, 49, 18]','[]',4,'gg-club 2568732-943133190554 · 74 · 구매가 650 (2026-09-20 싱크) [2026-09-23] Midfield Glow Up 1단계 완료(사용자 확인). ⚠️ current_ovr/six는 **카탈로그 단계 보상을 상한 규칙대로 얹은 산출값**이며 EA 실측이 아니다 — 다음 /club-sync에서 확정한다(런북 「완주 결과는 EA 싱크 실측으로」). ⚠️ current_attrs는 아직 갱신하지 않았다(GG Club이 28속성만 주므로 싱크로 받는다). [2026-09-23 2회차 club-sync] ⭐ EA 실측으로 확정됐다 — OVR 79는 산출값과 일치했으나 **PAS 69→74 · PHY 73→74로 산출이 과소 계상**이었다(실측 채택, 불변규칙 3). Role+도 산출 [4,14,16,49,18] → 실측 [18,4,14]로 2개 과다 계상이었다(1회차 싱크에서 정정). current_attrs도 이 회차 싱크로 채워졌다. [2026-09-24 3회차 club-sync · 사용자 보고 「보가르데는 진화 완료함」] ⭐ Midfield Glow Up **4단계 완주**가 EA 실측으로 확정됐다(Sync Club 직후 캡처): 6대 스탯 75/53/78/70/77/76 · Role+ [4,14,16,49,18]. 원장에는 1단계 행 하나만 있었으므로 2·3·4단계 행을 추가했다(단계 경계는 09-23 23:13 / 09-24 10:13 / 09-24 캡처의 속성 상한 일치로 판정). ⛔ 정정: current_playstyles에 있던 **Inventive는 오기**였다 — GG Club API 실측 playstyles=[8](Tiki Taka)뿐이고 playstylesPlus는 비어 있다. 카탈로그 산출값(path_json)을 실측 대신 썼던 루제리 사례와 같은 함정이다. ⚠️ 결손: 기준 카드 player_card_items.roles_plus가 []인데 EA 실측 Role+는 [4,14,18]에서 출발한다(진화 보상은 16·49뿐) — 기준 카드의 Role+ 수집 구멍이다.','2026-09-26',250,0,'2568732-943133190554-4','2026-09-26','{"가속": 75, "질주 속도": 75, "공격 위치 선정": 60, "결정력": 44, "슈팅력": 67, "중거리슛": 58, "발리 슛": 47, "페널티킥": 55, "시야": 77, "크로스": 75, "프리킥 정확도": 74, "짧은 패스": 80, "긴 패스": 79, "커브": 75, "민첩성": 58, "균형 감각": 65, "반응력": 73, "볼컨트롤": 73, "드리블": 71, "침착": 69, "차단력": 75, "헤딩 정확도": 60, "수비 위치 선정": 80, "스탠딩 태클": 80, "슬라이딩 태클": 76, "점프": 76, "체력": 76, "힘": 77, "공격성": 75, "다이빙": 9, "핸들링": 10, "킥": 11, "포지셔닝": 13, "반사신경": 10}',1,1,0,26,2,NULL);
